namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];

    public double AverageRating =>
        Ratings.Count > 0 ? Math.Round(Ratings.Average(), 1) : 0;

    public int RatingCount => Ratings.Count;
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int RecipeCount { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace RecipeCommunity.Models;

public class SubmitRecipeModel
{
    [Required(ErrorMessage = "Please enter a recipe title.")]
    [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be between 3 and 100 characters.")]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [StringLength(500, ErrorMessage = "Description cannot exceed 500 characters.")]
    public string Description { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please enter at least one ingredient.")]
    [MinLength(1, ErrorMessage = "Please enter at least one ingredient.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please enter at least one step.")]
    [MinLength(1, ErrorMessage = "Please enter at least one step.")]
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    private static readonly List<RecipeCategory> Categories =
    [
        new() { Name = "Breakfast", Icon = "🥞", Description = "Start your day right with hearty breakfast recipes" },
        new() { Name = "Lunch", Icon = "🥗", Description = "Quick and satisfying midday meals" },
        new() { Name = "Dinner", Icon = "🍝", Description = "Delicious dinner ideas for the whole family" },
        new() { Name = "Desserts", Icon = "🍰", Description = "Sweet treats and indulgent desserts" },
        new() { Name = "Snacks", Icon = "🍿", Description = "Light bites and tasty snacks" },
        new() { Name = "Drinks", Icon = "🥤", Description = "Refreshing beverages and cocktails" },
    ];

    public RecipeService()
    {
        _recipes = CreateSeedData();
        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public List<RecipeCategory> GetCategories()
    {
        return Categories.Select(c => new RecipeCategory
        {
            Name = c.Name,
            Icon = c.Icon,
            Description = c.Description,
            RecipeCount = _recipes.Count(r =>
                r.Category.Equals(c.Name, StringComparison.OrdinalIgnoreCase))
        }).ToList();
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes
            .Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase))
            .ToList();
    }

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public Recipe AddRecipe(SubmitRecipeModel model)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = model.Title,
            Category = model.Category,
            Description = model.Description,
            Ingredients = model.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = model.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
        };
        _recipes.Add(recipe);
        return recipe;
    }

    public void AddRating(int recipeId, int rating)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && rating is >= 1 and <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }

    public List<string> GetCategoryNames() => Categories.Select(c => c.Name).ToList();

    private static List<Recipe> CreateSeedData() =>
    [
        new()
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Description = "Fluffy golden pancakes perfect for a lazy weekend morning.",
            Ingredients = ["2 cups all-purpose flour", "2 tbsp sugar", "2 tsp baking powder", "1 tsp salt", "2 eggs", "1¾ cups milk", "¼ cup melted butter"],
            Steps = ["Mix dry ingredients in a large bowl.", "Whisk eggs, milk, and melted butter together.", "Combine wet and dry ingredients until just mixed.", "Heat a griddle over medium heat and grease lightly.", "Pour ¼ cup batter per pancake and cook until bubbles form.", "Flip and cook until golden brown."],
            Ratings = [5, 4, 5, 4, 5]
        },
        new()
        {
            Id = 2, Title = "Avocado Toast", Category = "Breakfast",
            Description = "Simple, trendy, and packed with healthy fats.",
            Ingredients = ["2 slices sourdough bread", "1 ripe avocado", "Salt and pepper to taste", "Red pepper flakes", "1 tbsp lemon juice"],
            Steps = ["Toast the bread until golden and crispy.", "Halve and pit the avocado, scoop into a bowl.", "Mash avocado with lemon juice, salt, and pepper.", "Spread onto toast and sprinkle with red pepper flakes."],
            Ratings = [4, 5, 4]
        },
        new()
        {
            Id = 3, Title = "Caesar Salad", Category = "Lunch",
            Description = "A crisp, savory classic with homemade dressing.",
            Ingredients = ["1 head romaine lettuce", "½ cup croutons", "¼ cup parmesan cheese", "2 tbsp Caesar dressing", "1 lemon"],
            Steps = ["Wash and chop the romaine lettuce.", "Toss with Caesar dressing.", "Top with croutons and shaved parmesan.", "Squeeze lemon over the top and serve."],
            Ratings = [4, 4, 3, 5]
        },
        new()
        {
            Id = 4, Title = "Spaghetti Bolognese", Category = "Dinner",
            Description = "A rich and hearty Italian meat sauce over pasta.",
            Ingredients = ["400g spaghetti", "500g ground beef", "1 onion, diced", "3 cloves garlic, minced", "800ml crushed tomatoes", "2 tbsp tomato paste", "1 tsp dried oregano", "Salt and pepper"],
            Steps = ["Cook spaghetti according to package directions.", "Brown the beef in a large pan, drain excess fat.", "Sauté onion and garlic until softened.", "Add crushed tomatoes, tomato paste, and oregano.", "Simmer for 20 minutes, season with salt and pepper.", "Serve sauce over spaghetti with parmesan."],
            Ratings = [5, 5, 4, 5, 5]
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Decadent individual cakes with a molten chocolate center.",
            Ingredients = ["200g dark chocolate", "150g butter", "3 eggs", "3 egg yolks", "¼ cup sugar", "2 tbsp flour"],
            Steps = ["Preheat oven to 220°C (425°F).", "Melt chocolate and butter together.", "Whisk eggs, yolks, and sugar until thick.", "Fold chocolate mixture into eggs, then fold in flour.", "Pour into greased ramekins.", "Bake 12-14 minutes until edges are firm but center is soft."],
            Ratings = [5, 5, 5, 4]
        },
        new()
        {
            Id = 6, Title = "Trail Mix", Category = "Snacks",
            Description = "A customizable mix of nuts, seeds, and dried fruit.",
            Ingredients = ["1 cup almonds", "1 cup cashews", "½ cup dried cranberries", "½ cup dark chocolate chips", "¼ cup sunflower seeds"],
            Steps = ["Combine all ingredients in a large bowl.", "Toss to mix evenly.", "Store in an airtight container."],
            Ratings = [4, 3, 4]
        },
        new()
        {
            Id = 7, Title = "Mango Smoothie", Category = "Drinks",
            Description = "A tropical, creamy smoothie bursting with mango flavor.",
            Ingredients = ["1 cup frozen mango chunks", "1 banana", "½ cup yogurt", "½ cup orange juice", "1 tbsp honey"],
            Steps = ["Add all ingredients to a blender.", "Blend until smooth and creamy.", "Pour into a glass and enjoy immediately."],
            Ratings = [5, 4, 5]
        },
        new()
        {
            Id = 8, Title = "Grilled Chicken Wrap", Category = "Lunch",
            Description = "A protein-packed wrap with fresh vegetables.",
            Ingredients = ["2 chicken breasts", "4 flour tortillas", "1 cup mixed greens", "1 tomato, sliced", "¼ cup ranch dressing", "Salt and pepper"],
            Steps = ["Season chicken with salt and pepper, grill until cooked through.", "Slice chicken into strips.", "Warm tortillas in a dry pan.", "Layer greens, chicken, tomato, and ranch on each tortilla.", "Roll up tightly and slice in half."],
            Ratings = [4, 5, 4, 4]
        },
    ];
}

