arguments.file_text:
@rendermode InteractiveServer

<div class="star-rating">
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= (_hoverRating ?? _selectedRating) ? "filled" : "")"
                  @onclick="() => OnStarClick(star)"
                  @onmouseover="() => _hoverRating = star"
                  @onmouseout="() => _hoverRating = null"
                  role="button"
                  title="Rate @star star@(star > 1 ? "s" : "")">
                ★
            </span>
        }
    </div>
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
    else
    {
        <span class="rating-hint">Click to rate</span>
    }
    <span class="rating-summary">@AverageRating / 5 (@RatingCount ratings)</span>
</div>

@code {
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Parameter] public EventCallback<int> OnRated { get; set; }

    private int _selectedRating;
    private int? _hoverRating;
    private bool _submitted;

    private async Task OnStarClick(int rating)
    {
        if (_submitted) return;
        _selectedRating = rating;
        _submitted = true;
        await OnRated.InvokeAsync(rating);
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.stars {
    display: flex;
    gap: 0.15rem;
}

.star {
    font-size: 1.8rem;
    color: #ccc;
    cursor: pointer;
    transition: color 0.15s, transform 0.15s;
    user-select: none;
}

.star:hover {
    transform: scale(1.2);
}

.star.filled {
    color: #f5a623;
}

.rating-hint {
    font-size: 0.85rem;
    color: #999;
}

.rating-thanks {
    font-size: 0.85rem;
    color: #28a745;
    font-weight: 600;
}

.rating-summary {
    font-size: 0.85rem;
    color: #666;
}

.hero {
    text-align: center;
    padding: 2rem 1rem;
    margin-bottom: 2rem;
    background: linear-gradient(135deg, #ff6b35, #f7931e);
    color: white;
    border-radius: 12px;
}

.hero h1 {
    font-size: 2.5rem;
    margin-bottom: 0.5rem;
}

.hero .lead {
    font-size: 1.15rem;
    opacity: 0.95;
}

.section-title {
    margin-bottom: 1.25rem;
    color: #333;
}

.categories-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: 1.25rem;
    margin-bottom: 2.5rem;
}

.category-card {
    display: block;
    padding: 1.5rem;
    border: 1px solid #e0e0e0;
    border-radius: 10px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s, transform 0.2s;
    background: #fff;
}

.category-card:hover {
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
    transform: translateY(-2px);
    text-decoration: none;
    color: inherit;
}

.category-icon {
    font-size: 2.5rem;
}

.category-card h3 {
    margin: 0.5rem 0 0.25rem;
    color: #333;
}

.category-card p {
    color: #666;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
}

.recipe-count {
    font-size: 0.8rem;
    color: #999;
    font-weight: 600;
    text-transform: uppercase;
}

.cta-section {
    text-align: center;
    padding: 2rem;
    background: #f8f9fa;
    border-radius: 10px;
}

.cta-section h2 {
    color: #333;
}

.cta-section p {
    color: #666;
    margin-bottom: 1rem;
}

@page "/category/{CategoryName}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services

@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — Recipe Community</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (Recipes.Count == 0)
{
    <div class="alert alert-info">
        No recipes found in this category yet. <a href="/submit">Be the first to add one!</a>
    </div>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in Recipes)
        {
            <a href="/recipe/@recipe.Id" class="recipe-list-item">
                <div class="recipe-info">
                    <h3>@recipe.Title</h3>
                    <p>@recipe.Description</p>
                </div>
                <div class="recipe-meta">
                    @if (recipe.RatingCount > 0)
                    {
                        <span class="rating">★ @recipe.AverageRating</span>
                        <span class="count">@recipe.RatingCount ratings</span>
                    }
                    else
                    {
                        <span class="count">No ratings yet</span>
                    }
                </div>
            </a>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        var formatted = System.Globalization.CultureInfo.CurrentCulture.TextInfo
            .ToTitleCase(CategoryName.ToLower());
        CategoryName = formatted;
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

.recipe-list {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.recipe-list-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.25rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s;
    background: #fff;
}

.recipe-list-item:hover {
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.1);
    text-decoration: none;
    color: inherit;
}

.recipe-info h3 {
    margin: 0 0 0.25rem;
    color: #333;
}

.recipe-info p {
    margin: 0;
    color: #666;
    font-size: 0.9rem;
}

.recipe-meta {
    text-align: right;
    white-space: nowrap;
}

.recipe-meta .rating {
    display: block;
    font-size: 1.1rem;
    color: #f5a623;
    font-weight: 700;
}

.recipe-meta .count {
    font-size: 0.8rem;
    color: #999;
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@using RecipeCommunity.Components.Shared

@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe Not Found") — Recipe Community</PageTitle>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-outline-secondary">Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@Recipe.Category.ToLower()">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <article class="recipe-detail">
        <h1>@Recipe.Title</h1>
        <p class="recipe-description">@Recipe.Description</p>

        <div class="rating-section">
            <h4>Rate this recipe</h4>
            <StarRating AverageRating="@Recipe.AverageRating"
                        RatingCount="@Recipe.RatingCount"
                        OnRated="HandleRating" />
        </div>

        <section class="recipe-section">
            <h2>🧾 Ingredients</h2>
            <ul class="ingredients-list">
                @foreach (var ingredient in Recipe.Ingredients)
                {
                    <li>@ingredient</li>
                }
            </ul>
        </section>

        <section class="recipe-section">
            <h2>👩‍🍳 Steps</h2>
            <ol class="steps-list">
                @foreach (var step in Recipe.Steps)
                {
                    <li>@step</li>
                }
            </ol>
        </section>
    </article>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }

    private void HandleRating(int rating)
    {
        RecipeService.AddRating(Id, rating);
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

.recipe-detail h1 {
    margin-bottom: 0.25rem;
}

.recipe-description {
    font-size: 1.1rem;
    color: #555;
    margin-bottom: 1.5rem;
}

.rating-section {
    background: #f8f9fa;
    padding: 1.25rem;
    border-radius: 8px;
    margin-bottom: 2rem;
}

.rating-section h4 {
    margin-top: 0;
    margin-bottom: 0.75rem;
}

.recipe-section {
    margin-bottom: 2rem;
}

.recipe-section h2 {
    font-size: 1.4rem;
    margin-bottom: 0.75rem;
    color: #333;
}

