@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services

@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — Recipe Community</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">Submit Recipe</li>
    </ol>
</nav>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted!</h4>
        <p>Your recipe "<strong>@_submittedTitle</strong>" has been added.</p>
        <a href="/recipe/@_submittedId" class="btn btn-success me-2">View Recipe</a>
        <button class="btn btn-outline-secondary" @onclick="ResetForm">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g. Grandma's Apple Pie" />
            <ValidationMessage For="() => _model.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                <option value="">— Select a category —</option>
                @foreach (var cat in RecipeService.GetCategoryNames())
                {
                    <option value="@cat">@cat</option>
                }
            </InputSelect>
            <ValidationMessage For="() => _model.Category" />
        </div>

        <div class="mb-3">
            <label for="description" class="form-label">Short Description</label>
            <InputTextArea id="description" class="form-control" @bind-Value="_model.Description" rows="2"
                           placeholder="A brief description of your recipe" />
            <ValidationMessage For="() => _model.Description" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" @bind-Value="_model.Ingredients" rows="5"
                           placeholder="Enter one ingredient per line&#10;e.g.&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => _model.Ingredients" />
            <div class="form-text">Enter one ingredient per line.</div>
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" @bind-Value="_model.Steps" rows="6"
                           placeholder="Enter one step per line&#10;e.g.&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
            <ValidationMessage For="() => _model.Steps" />
            <div class="form-text">Enter one step per line.</div>
        </div>

        <button type="submit" class="btn btn-primary btn-lg">Submit Recipe</button>
    </EditForm>
}

@code {
    private SubmitRecipeModel _model = new();
    private bool _submitted;
    private string _submittedTitle = string.Empty;
    private int _submittedId;

    private void HandleSubmit()
    {
        var recipe = RecipeService.AddRecipe(_model);
        _submittedTitle = recipe.Title;
        _submittedId = recipe.Id;
        _submitted = true;
    }

    private void ResetForm()
    {
        _model = new SubmitRecipeModel();
        _submitted = false;
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    <div class="stars">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span class="star @(star <= (_hoverRating ?? _selectedRating) ? "filled" : "")"
                  @onclick="() => OnStarClick(star)"
                  @onmouseover="() => _hoverRating = star"
                  @onmouseout="() => _hoverRating = null"
                  role="button"
                  title="Rate @star star@(star > 1 ? "s" : "")">
                ★
            </span>
        }
    </div>
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
    else
    {
        <span class="rating-hint">Click to rate</span>
    }
    <span class="rating-summary">@AverageRating / 5 (@RatingCount ratings)</span>
</div>

@code {
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Parameter] public EventCallback<int> OnRated { get; set; }

    private int _selectedRating;
    private int? _hoverRating;
    private bool _submitted;

    private async Task OnStarClick(int rating)
    {
        if (_submitted) return;
        _selectedRating = rating;
        _submitted = true;
        await OnRated.InvokeAsync(rating);
    }
}

.star-rating {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    flex-wrap: wrap;
}

.stars {
    display: flex;
    gap: 0.15rem;
}

.star {
    font-size: 1.8rem;
    color: #ccc;
    cursor: pointer;
    transition: color 0.15s, transform 0.15s;
    user-select: none;
}

.star:hover {
    transform: scale(1.2);
}

.star.filled {
    color: #f5a623;
}

.rating-hint {
    font-size: 0.85rem;
    color: #999;
}

.rating-thanks {
    font-size: 0.85rem;
    color: #28a745;
    font-weight: 600;
}

.rating-summary {
    font-size: 0.85rem;
    color: #666;
}

.hero {
    text-align: center;
    padding: 2rem 1rem;
    margin-bottom: 2rem;
    background: linear-gradient(135deg, #ff6b35, #f7931e);
    color: white;
    border-radius: 12px;
}

.hero h1 {
    font-size: 2.5rem;
    margin-bottom: 0.5rem;
}

.hero .lead {
    font-size: 1.15rem;
    opacity: 0.95;
}

.section-title {
    margin-bottom: 1.25rem;
    color: #333;
}

.categories-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: 1.25rem;
    margin-bottom: 2.5rem;
}

.category-card {
    display: block;
    padding: 1.5rem;
    border: 1px solid #e0e0e0;
    border-radius: 10px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s, transform 0.2s;
    background: #fff;
}

.category-card:hover {
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.12);
    transform: translateY(-2px);
    text-decoration: none;
    color: inherit;
}

.category-icon {
    font-size: 2.5rem;
}

.category-card h3 {
    margin: 0.5rem 0 0.25rem;
    color: #333;
}

.category-card p {
    color: #666;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
}

.recipe-count {
    font-size: 0.8rem;
    color: #999;
    font-weight: 600;
    text-transform: uppercase;
}

.cta-section {
    text-align: center;
    padding: 2rem;
    background: #f8f9fa;
    border-radius: 10px;
}

.cta-section h2 {
    color: #333;
}

.cta-section p {
    color: #666;
    margin-bottom: 1rem;
}

@page "/category/{CategoryName}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services

@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes — Recipe Community</PageTitle>

<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

<h1>@CategoryName Recipes</h1>

@if (Recipes.Count == 0)
{
    <div class="alert alert-info">
        No recipes found in this category yet. <a href="/submit">Be the first to add one!</a>
    </div>
}
else
{
    <div class="recipe-list">
        @foreach (var recipe in Recipes)
        {
            <a href="/recipe/@recipe.Id" class="recipe-list-item">
                <div class="recipe-info">
                    <h3>@recipe.Title</h3>
                    <p>@recipe.Description</p>
                </div>
                <div class="recipe-meta">
                    @if (recipe.RatingCount > 0)
                    {
                        <span class="rating">★ @recipe.AverageRating</span>
                        <span class="count">@recipe.RatingCount ratings</span>
                    }
                    else
                    {
                        <span class="count">No ratings yet</span>
                    }
                </div>
            </a>
        }
    </div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> Recipes { get; set; } = [];

    protected override void OnParametersSet()
    {
        var formatted = System.Globalization.CultureInfo.CurrentCulture.TextInfo
            .ToTitleCase(CategoryName.ToLower());
        CategoryName = formatted;
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

.recipe-list {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.recipe-list-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 1.25rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s;
    background: #fff;
}

.recipe-list-item:hover {
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.1);
    text-decoration: none;
    color: inherit;
}

.recipe-info h3 {
    margin: 0 0 0.25rem;
    color: #333;
}

.recipe-info p {
    margin: 0;
    color: #666;
    font-size: 0.9rem;
}

.recipe-meta {
    text-align: right;
    white-space: nowrap;
}

.recipe-meta .rating {
    display: block;
    font-size: 1.1rem;
    color: #f5a623;
    font-weight: 700;
}

.recipe-meta .count {
    font-size: 0.8rem;
    color: #999;
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@using RecipeCommunity.Components.Shared

@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe Not Found") — Recipe Community</PageTitle>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-outline-secondary">Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@Recipe.Category.ToLower()">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <article class="recipe-detail">
        <h1>@Recipe.Title</h1>
        <p class="recipe-description">@Recipe.Description</p>

        <div class="rating-section">
            <h4>Rate this recipe</h4>
            <StarRating AverageRating="@Recipe.AverageRating"
                        RatingCount="@Recipe.RatingCount"
                        OnRated="HandleRating" />
        </div>

        <section class="recipe-section">
            <h2>🧾 Ingredients</h2>
            <ul class="ingredients-list">
                @foreach (var ingredient in Recipe.Ingredients)
                {
                    <li>@ingredient</li>
                }
            </ul>
        </section>

        <section class="recipe-section">
            <h2>👩‍🍳 Steps</h2>
            <ol class="steps-list">
                @foreach (var step in Recipe.Steps)
                {
                    <li>@step</li>
                }
            </ol>
        </section>
    </article>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }

    private void HandleRating(int rating)
    {
        RecipeService.AddRating(Id, rating);
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

