toolArgs.file_text:
@page "/recipe/{Id:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@using RecipeCommunity.Components.Shared

@inject RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe Not Found") — Recipe Community</PageTitle>

@if (Recipe is null)
{
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-outline-secondary">Back to Home</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@Recipe.Category.ToLower()">@Recipe.Category</a></li>
            <li class="breadcrumb-item active">@Recipe.Title</li>
        </ol>
    </nav>

    <article class="recipe-detail">
        <h1>@Recipe.Title</h1>
        <p class="recipe-description">@Recipe.Description</p>

        <div class="rating-section">
            <h4>Rate this recipe</h4>
            <StarRating AverageRating="@Recipe.AverageRating"
                        RatingCount="@Recipe.RatingCount"
                        OnRated="HandleRating" />
        </div>

        <section class="recipe-section">
            <h2>🧾 Ingredients</h2>
            <ul class="ingredients-list">
                @foreach (var ingredient in Recipe.Ingredients)
                {
                    <li>@ingredient</li>
                }
            </ul>
        </section>

        <section class="recipe-section">
            <h2>👩‍🍳 Steps</h2>
            <ol class="steps-list">
                @foreach (var step in Recipe.Steps)
                {
                    <li>@step</li>
                }
            </ol>
        </section>
    </article>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }

    private void HandleRating(int rating)
    {
        RecipeService.AddRating(Id, rating);
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

